//! Owner authority: a credential distinct from the daemon's general API token.
//!
//! The API token is also what the CLI and every local client hold, so on its
//! own it must not be enough to export model keys to a paired host or to make a
//! desktop an administrator. Those operations additionally require the owner
//! key in the `x-praxi-owner-key` header:
//!
//! * desktop app: a random per-launch secret generated by the app, handed to
//!   the daemon on its standard input (never argv, never a file), kept only in
//!   memory on both sides and given to the web view by a Tauri command that
//!   only the main window may call;
//! * headless host: the `owner-key` file in the data dir (0600), read by the
//!   host's own `bot host ...` commands.
//!
//! A daemon that has no owner key refuses these operations. The key is never
//! handed to bots, tools, CLI engines or the MCP facade. Against a bot that
//! the owner gave an unrestricted shell on the same OS account this is damping
//! (the same standing as the shell never-list); it is a boundary against bots
//! without shell, CLI engines, the MCP mode and any holder of only the token.

use axum::http::HeaderMap;

use crate::{ApiError, AppState};

/// Request header carrying the owner key.
pub const OWNER_HEADER: &str = "x-praxi-owner-key";

/// Stable code when the owner key is missing or wrong.
pub const OWNER_REQUIRED: &str = "owner_key_required";

impl AppState {
    /// Install the owner key (once, at start).
    pub fn set_owner_key(&self, key: String) {
        if key.len() >= 32 {
            let _ = self.0.owner_key.set(key);
        }
    }

    /// Whether `headers` carry the owner key.
    pub(crate) fn owner_ok(&self, headers: &HeaderMap) -> bool {
        let (Some(expected), Some(given)) = (
            self.0.owner_key.get(),
            headers.get(OWNER_HEADER).and_then(|v| v.to_str().ok()),
        ) else {
            return false;
        };
        let (a, b) = (expected.as_bytes(), given.trim().as_bytes());
        a.len() == b.len() && a.iter().zip(b).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
    }

    /// Refuse unless the owner key is presented.
    pub(crate) fn require_owner(&self, headers: &HeaderMap) -> Result<(), ApiError> {
        if self.owner_ok(headers) {
            Ok(())
        } else {
            Err(ApiError::new(
                axum::http::StatusCode::FORBIDDEN,
                OWNER_REQUIRED,
                "this needs the owner key: start Praxi from the desktop app, or run it on the host with its owner key",
            ))
        }
    }
}
